@file:OptIn(kotlin.io.encoding.ExperimentalEncodingApi::class)

package dev.kmpyt

import kotlin.io.encoding.Base64

/**
 * Newly generated test media; no downloaded/platform media or application assets.
 * ffmpeg -f lavfi -i color=c=red:s=32x32:r=5:d=0.6 -an -c:v libx264 -profile:v baseline -pix_fmt yuv420p -movflags +faststart authored-red.mp4
 * ffmpeg -f lavfi -i sine=frequency=440:sample_rate=44100:duration=0.6 -vn -c:a aac -b:a 24k -movflags +faststart authored-tone.m4a
 * Embedded because Kotlin/Native simulator tests do not automatically bundle test resources.
 */
internal object IosAuthoredMedia {
    val video: ByteArray get() = Base64.decode("")
    val audio: ByteArray get() = Base64.decode("")
}
